def solve(coins, amount):
    """Fewest coins (unlimited supply) summing to amount, or -1 if impossible."""
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        best = INF
        for coin in coins:
            if coin > 0 and coin <= a and dp[a - coin] + 1 < best:
                best = dp[a - coin] + 1
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

