def solve(s):
    # Longest palindromic substring via expand-around-center.
    if not s:
        return ''
    start, end = 0, 0
    n = len(s)
    for i in range(n):
        # odd-length centers
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        if r - l - 1 > end - start + 1:
            start, end = l + 1, r - 1
        # even-length centers
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        if r - l - 1 > end - start + 1:
            start, end = l + 1, r - 1
    return s[start:end + 1]

