def solve(coins, amount):
    """Return the fewest number of coins that sum to amount using unlimited
    coins of each value, or -1 if impossible. Classic bottom-up DP."""
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if 0 < c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

